 final MainActivity app;JSONObject s;final int id,me;final int[] b=new int[200],aux=new int[200];final ArrayList<int[]> moves=new ArrayList<>();final Paint p=new Paint(3);final ArrayList<RectF> hit=new ArrayList<>();int selected=-1;float w,ox,oy;int[] animationBoard;long animationStart;int animationSeq=-1;
 final ChessPieces chessPieces=new ChessPieces();
