 public void update(JSONObject state,boolean animate){s=state;JSONArray arr=s.optJSONArray("b"),other=s.optJSONArray("aux");for(int i=0;i<200;i++){b[i]=arr==null?0:arr.optInt(i);aux[i]=other==null?0:other.optInt(i);}moves.clear();JSONArray legal=s.optJSONArray("moves");if(legal!=null)for(int i=0;i<legal.length();i++){JSONArray m=legal.optJSONArray(i);moves.add(new int[]{m.optInt(0),m.optInt(1)});}if(animate&&id==9&&s.optInt("seq")!=animationSeq&&s.optJSONArray("before")!=null&&s.optJSONArray("before").length()>=14){animationSeq=s.optInt("seq");animationBoard=new int[14];for(int i=0;i<14;i++)animationBoard[i]=s.optJSONArray("before").optInt(i);animationStart=android.os.SystemClock.uptimeMillis();}setContentDescription(Game.NAMES[id]+". "+s.optString("lastMove"));invalidate();}
 public int heightDp(){return 320;}
